(()=>{'use strict';const key='yapiguc-accessibility-v1',body=document.body;if(!body||document.querySelector('#yg-access-panel'))return;let state={text:'normal',contrast:false,motion:false};try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved)state={text:['normal','large','larger'].includes(saved.text)?saved.text:'normal',contrast:saved.contrast===true,motion:saved.motion===true};}catch{}
const wrap=document.createElement('aside');wrap.className='yg-accessibility';wrap.setAttribute('aria-label','Görünüm ve erişilebilirlik tercihleri');wrap.innerHTML='<button type="button" class="yg-access-toggle" aria-expanded="false" aria-controls="yg-access-panel">Erişilebilirlik</button><section id="yg-access-panel" aria-labelledby="yg-access-title" hidden><div class="yg-access-heading"><h2 id="yg-access-title">Erişilebilirlik seçenekleri</h2><button type="button" data-access-close aria-label="Erişilebilirlik panelini kapat">×</button></div><p>Okuma görünümünü size uygun hâle getirin.</p><label for="yg-access-text">Metin boyutu</label><select id="yg-access-text"><option value="normal">Standart</option><option value="large">Büyük</option><option value="larger">Daha büyük</option></select><label class="yg-access-check"><input type="checkbox" id="yg-access-contrast">Yüksek kontrast</label><label class="yg-access-check"><input type="checkbox" id="yg-access-motion">Hareketleri azalt</label><button type="button" class="yg-access-reset">Standart görünüme dön</button><p class="yg-access-note">Tercihler yalnızca bu tarayıcıda saklanır.</p></section>';body.append(wrap);
const button=wrap.querySelector('.yg-access-toggle'),panel=wrap.querySelector('#yg-access-panel'),text=wrap.querySelector('#yg-access-text'),contrast=wrap.querySelector('#yg-access-contrast'),motion=wrap.querySelector('#yg-access-motion');
function apply(save=false){body.dataset.accessText=state.text;body.dataset.accessContrast=String(state.contrast);body.dataset.accessMotion=String(state.motion);text.value=state.text;contrast.checked=state.contrast;motion.checked=state.motion;if(save)try{localStorage.setItem(key,JSON.stringify(state));}catch{}}
function close(){panel.hidden=true;button.setAttribute('aria-expanded','false');button.focus();}
button.addEventListener('click',()=>{const open=panel.hidden;panel.hidden=!open;button.setAttribute('aria-expanded',String(open));if(open)text.focus();});wrap.querySelector('[data-access-close]').addEventListener('click',close);panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();}});
for(const control of [text,contrast,motion])control.addEventListener('change',()=>{state={text:text.value,contrast:contrast.checked,motion:motion.checked};apply(true);});wrap.querySelector('.yg-access-reset').addEventListener('click',()=>{state={text:'normal',contrast:false,motion:false};apply(true);});apply();
})();